import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{reproFigure}from './repro-figures.js?v=20261023-physicscomplete01';import{buildRepro}from './repro-meshes.js?v=20261023-physicscomplete01';
export function showRepro(spec='cycle',w={}){let[k]=spec.split(':'),o={kind:k,progress:.5,...w},name=w.title||({puberty:'Reproductive hormone pathways',cycle:'Ovary and uterus: linked events',feedback:'Hormone interactions',graph:'Read the illustrative hormone curves',methods:'Compare contraception mechanisms',ivf:'Laboratory fertilisation and transfer',evidence:'Evaluate supplied evidence','ivf-evidence':'Evaluate fertility treatment'})[k],figure=reproFigure(o);if(!['puberty','cycle','ivf'].includes(k)||o.concealed){renderDiagram(name,w.label||'Original schematic or supplied evidence',figure,'REPRODUCTION AND HORMONAL CONTROL');return;}renderCustomModel({name,formula:w.label||'Schematic organs/cells · use the labelled diagram',kicker:'SCHEMATIC PROCESS STRUCTURES',aria:name+'. Simplified educational structures; paired diagram available.',atoms:[],bonds:[],radius:2.3,viewKey:'repro-'+k,startPaused:true,note:'Symbolic scale and timing · real cycles and outcomes vary',diagram:figure,build:(g,T)=>buildRepro(g,T,o)});}
